class TemperaturaInvalida(ValueError):
    def __init__(self, grados):
        super().__init__(f"{grados} ºC está por debajo del cero absoluto")
        self.grados = grados


def leer_temperatura(texto):
    grados = float(texto)          # puede lanzar ValueError o TypeError
    if grados < -273.15:
        raise TemperaturaInvalida(grados)
    return grados


for dato in ["21.5", "-300", "calor", None]:
    try:
        t = leer_temperatura(dato)
    except TemperaturaInvalida as e:      # la subclase, ANTES que su madre
        print("Propia:", e, "| args:", e.args)
    except (ValueError, TypeError) as e:  # tupla de excepciones
        print(type(e).__name__, "con", repr(dato))
    else:
        print("Correcta:", t)
    finally:
        print("  (finally se ejecuta siempre)")

